def by_category() -> Dict[str, List[Dict[str, Any]]]:
    out: Dict[str, List[Dict[str, Any]]] = {k: [] for k, _ in CATEGORIES}
    for s in SCENARIOS:
        out.setdefault(s["category"], []).append(s)
    return out


def objectives() -> List[Dict[str, Any]]:
    """벤치/판정 호환 objective 리스트 (id·description·action_keywords + 메타)."""
    return [dict(s) for s in SCENARIOS]


def scenario_by_id(sid: str):
    for s in SCENARIOS:
        if s["id"] == sid:
            return s
    return None


